Q.1.The following program implement array using STL. What will be the output of the following
program?
#include<iostream>
#include<array>
using namespace std;
int main()
{
array<int,6> ar = {11, 21, 31, 41, 51, 61};
array<int,6> ar1 = {71, 81, 91, 10, 11, 12};
cout << "1st Ary before swapping are : ";
for (int i=0; i<6; i++)
cout << ar[i] << " ";
cout << endl;
cout << "2nd Ary before swapping are: ";
for (int i=0; i<6; i++)
cout << ar1[i] << " ";
cout << endl;
ar.swap(ar1);
cout << "1st Ary after swapping are: ";

(Q1 continued)
for (int i=0; i<6; i++)
cout << ar[i] << " ";
cout << endl;
cout << "2nd Ary after swapping are: ";
